package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.content.contraptions.*;
import com.simibubi.create.content.contraptions.pulley.*;
import com.simibubi.create.content.contraptions.glue.SuperGlueEntity;
import com.simibubi.create.content.kinetics.KineticGraph;
import com.simibubi.create.content.kinetics.transmission.sequencer.*;
import com.simibubi.create.foundation.mixin.accessor.ServerLevelEntityManagerAccessor;
import it.unimi.dsi.fastutil.longs.Long2ObjectMap;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.*;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.entity.PersistentEntitySectionManager;
import net.minecraft.world.phys.Vec3;

/** Isolated next-stage tests: no compilation or native execution claim until root integration. */
public class PulleyGameTests {
    private static final BlockPos B=new BlockPos(3,6,3),BODY=B.below(3);
    private static ItemStack cargo(){var stack=new ItemStack(Items.DIAMOND,7);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Native pulley cargo"));return stack;}
    private static boolean exact(ItemStack stack){return stack.getCount()==7&&ItemStack.isSameItemSameComponents(stack,cargo());}
    private static PulleyBlockEntity setup(GameTestHelper h,boolean water){
        h.setBlock(B,AllBlocks.ROPE_PULLEY);h.setBlock(B.below(),AllBlocks.ROPE.defaultBlockState().setValue(BlockStateProperties.WATERLOGGED,water));h.setBlock(B.below(2),AllBlocks.PULLEY_MAGNET.defaultBlockState().setValue(BlockStateProperties.WATERLOGGED,water));h.setBlock(BODY,Blocks.BARREL);h.getBlockEntity(BODY,BarrelBlockEntity.class).setItem(0,cargo());return h.getBlockEntity(B,PulleyBlockEntity.class);
    }
    private static void drive(PulleyBlockEntity pulley,float speed){pulley.setNetworkState(speed,speed,false,new KineticGraph.Stress(512,64,false),Map.of(Direction.WEST,speed));}
    private static void tick(GameTestHelper h,PulleyBlockEntity pulley,int count){for(int i=0;i<count;i++)PulleyBlockEntity.tick(h.getLevel(),h.absolutePos(B),h.getBlockState(B),pulley);}
    private static LinearContraptionEntity start(GameTestHelper h,PulleyBlockEntity pulley,float speed)throws Exception{drive(pulley,speed);h.assertTrue(pulley.assemble(),"Native pulley assembly accepted");var owner=pulley.getMovedContraption();h.assertTrue(owner!=null&&owner.getType()==AllEntityTypes.LINEAR_CONTRAPTION&&owner.hasOwnedStructure(),"Real registered native linear owner");return owner;}
    private static void owned(GameTestHelper h,LinearContraptionEntity owner){h.assertTrue(exact(owner.getContraption().getStorage().getAllItemStorages().get(BlockPos.ZERO).getStackInSlot(0)),"Exactly seven named diamonds have one actual moving owner");}
    @GameTest public void actualCaptureRemovesRopesAndBodyOnlyAfterNativeOwnerReservation(GameTestHelper h)throws Exception{var pulley=setup(h,false);var owner=start(h,pulley,16);h.assertTrue(owner.getContraption() instanceof PulleyContraption c&&c.getInitialOffset()==2&&c.getBlocks().size()==1,"Only body cells belong to the real owner; rope length is controller metadata");h.assertTrue(owner.position().distanceToSqr(Vec3.atLowerCornerOf(h.absolutePos(BODY)))<1e-12,"Nonzero initial extension preserves the real source body anchor");h.assertBlockPresent(Blocks.AIR,B.below());h.assertBlockPresent(Blocks.AIR,B.below(2));h.assertBlockPresent(Blocks.AIR,BODY);owned(h,owner);h.succeed();}
    @GameTest public void positiveNativeInputMovesTheActualBodyDownAndNegativeInputRetractsIt(GameTestHelper h)throws Exception{var pulley=setup(h,false);var owner=start(h,pulley,64);tick(h,pulley,3);float down=pulley.offset;h.assertTrue(down>2&&owner.getY()<h.absolutePos(BODY).getY(),"Positive source RPM pays out and moves the real native body down");drive(pulley,-64);tick(h,pulley,3);h.assertTrue(pulley.offset<down&&owner.getY()>h.absolutePos(BODY).getY()-(down-2),"Negative source RPM retracts the same original native body");owned(h,owner);h.succeed();}
    @GameTest public void nativeStopRestoresExactCargoAndPhysicalRopeMagnetAtGridOffset(GameTestHelper h)throws Exception{var pulley=setup(h,false);var owner=start(h,pulley,16);h.assertTrue(pulley.disassemble()&&owner.isRemoved(),"Real body retires only after world ownership completes");h.assertBlockPresent(AllBlocks.ROPE,B.below());h.assertBlockPresent(AllBlocks.PULLEY_MAGNET,B.below(2));h.assertTrue(exact(h.getBlockEntity(BODY,BarrelBlockEntity.class).getItem(0))&&!pulley.isRunning(),"Exact source cargo and controller state restore once");h.succeed();}
    @GameTest public void waterloggedRopesLeaveNativeWaterAndRecoverTheirSourceFluidFlags(GameTestHelper h)throws Exception{var pulley=setup(h,true);start(h,pulley,16);h.assertBlockPresent(Blocks.WATER,B.below());h.assertBlockPresent(Blocks.WATER,B.below(2));h.assertTrue(pulley.disassemble(),"Native waterlogged body restoration succeeds");h.assertTrue(h.getBlockState(B.below()).getValue(BlockStateProperties.WATERLOGGED)&&h.getBlockState(B.below(2)).getValue(BlockStateProperties.WATERLOGGED),"Both source rope and magnet recover waterlogging without fluid cargo copies");h.succeed();}
    private static final class DuplicateReservation extends PulleyBlockEntity{UUID rejected;DuplicateReservation(BlockPos pos,net.minecraft.world.level.block.state.BlockState state){super(pos,state);}@Override protected LinearContraptionEntity createReservation(ServerLevel server){var owner=super.createReservation(server);owner.setUUID(rejected);return owner;}}
    @GameTest public void rejectedNativeBodyReservationCannotRemoveSourceRopesOrNamedCargo(GameTestHelper h)throws Exception{setup(h,false);var marker=new ControlledContraptionEntity(AllEntityTypes.CONTROLLED_CONTRAPTION,h.getLevel());h.assertTrue(h.getLevel().addFreshEntity(marker),"Real duplicate-UUID marker accepted");try{var replacement=new DuplicateReservation(h.absolutePos(B),h.getBlockState(B));replacement.rejected=marker.getUUID();replacement.setLevel(h.getLevel());h.getLevel().setBlockEntity(replacement);drive(replacement,16);var refused=false;try{replacement.assemble();}catch(AssemblyException expected){refused=true;}h.assertTrue(refused&&!replacement.isRunning()&&replacement.getMovedContraption()==null,"Real native duplicate owner admission refuses before source mutation");h.assertBlockPresent(AllBlocks.ROPE,B.below());h.assertBlockPresent(AllBlocks.PULLEY_MAGNET,B.below(2));h.assertTrue(exact(h.getBlockEntity(BODY,BarrelBlockEntity.class).getItem(0)),"Refused reservation leaves exact world cargo untouched");}finally{marker.discard();}h.succeed();}
    @SuppressWarnings("unchecked") private static void unavailable(GameTestHelper h,Runnable body)throws Exception{var manager=((ServerLevelEntityManagerAccessor)h.getLevel()).create$getEntityManager();var f=PersistentEntitySectionManager.class.getDeclaredField("chunkLoadStatuses");f.setAccessible(true);var data=(Long2ObjectMap<Object>)f.get(manager);long key=ChunkPos.pack(h.absolutePos(BODY));var saved=data.remove(key);try{body.run();}finally{data.put(key,saved);}}
    @GameTest public void missingNativeEntityDataRefusesCaptureBeforeEitherRopesOrBodyChangeOwner(GameTestHelper h)throws Exception{var pulley=setup(h,false);drive(pulley,16);unavailable(h,()->{boolean refused=false;try{pulley.assemble();}catch(AssemblyException expected){refused=true;}h.assertTrue(refused&&!pulley.isRunning(),"Native source data preflight refuses before mutation");h.assertBlockPresent(AllBlocks.ROPE,B.below());h.assertTrue(exact(h.getBlockEntity(BODY,BarrelBlockEntity.class).getItem(0)),"Original world cargo remains untouched");});h.assertTrue(pulley.assemble(),"Source becomes capturable after actual native readiness returns");h.succeed();}
    @GameTest public void missingRestorationDataRetainsOriginalBodyUuidCargoAndVirtualRopeLength(GameTestHelper h)throws Exception{var pulley=setup(h,false);var owner=start(h,pulley,16);unavailable(h,()->{h.assertFalse(pulley.disassemble(),"Native restore preflight refuses unavailable data");h.assertTrue(pulley.getMovedContraption()==owner&&owner.isAlive()&&pulley.offset==2&&pulley.hasVirtualRopes(),"Exact real owner and extension metadata remain durable");owned(h,owner);h.assertBlockPresent(Blocks.AIR,BODY);});h.assertTrue(pulley.disassemble()&&exact(h.getBlockEntity(BODY,BarrelBlockEntity.class).getItem(0)),"Retry restores the same original cargo exactly once");h.succeed();}
    @GameTest public void nativeLoadBeforeLevelReattachesTheOriginalSavedBodyAndOffset(GameTestHelper h)throws Exception{var pulley=setup(h,false);var owner=start(h,pulley,16);tick(h,pulley,3);float offset=pulley.offset;var data=pulley.saveWithFullMetadata(h.getLevel().registryAccess());var copy=(PulleyBlockEntity)BlockEntity.loadStatic(h.absolutePos(B),h.getBlockState(B),data,h.getLevel().registryAccess());h.assertTrue(copy.getLevel()==null&&copy.offset==offset&&copy.hasVirtualRopes(),"Native load-before-level retains extension and removed-rope ownership metadata");copy.setLevel(h.getLevel());h.getLevel().setBlockEntity(copy);h.assertTrue(copy.getMovedContraption()==owner&&copy.getInitialRopeOffset()==2,"Reload resolves the original actual UUID, never a new body");owned(h,owner);h.succeed();}
    @GameTest public void unresolvedSavedBodyUuidCannotBeClearedByRunningFlagOrMovementCapture(GameTestHelper h)throws Exception{var pulley=setup(h,false);var id=UUID.randomUUID();var data=pulley.saveWithFullMetadata(h.getLevel().registryAccess());data.putBoolean("Running",false);data.store("MovedEntity",UUIDUtil.CODEC,id);var copy=(PulleyBlockEntity)BlockEntity.loadStatic(h.absolutePos(B),h.getBlockState(B),data,h.getLevel().registryAccess());copy.setLevel(h.getLevel());h.getLevel().setBlockEntity(copy);h.assertFalse(copy.disassembleForMovement(),"Absent original native UUID refuses enclosing controller movement");h.assertTrue(copy.saveWithFullMetadata(h.getLevel().registryAccess()).read("MovedEntity",UUIDUtil.CODEC).orElseThrow().equals(id),"Unresolved original owner identity remains durable");h.succeed();}
    @GameTest public void emptyNativeRopeAdvancesWithoutInventingAnEmptyCargoEntity(GameTestHelper h)throws Exception{h.setBlock(B,AllBlocks.ROPE_PULLEY);var pulley=h.getBlockEntity(B,PulleyBlockEntity.class);drive(pulley,16);h.assertTrue(pulley.assemble(),"Native empty source rope starts");tick(h,pulley,20);h.assertTrue(pulley.isRunning()&&pulley.getMovedContraption()==null&&pulley.offset>0,"Real empty rope advances under native RPM with no invented owned entity");h.assertFalse(pulley.saveWithFullMetadata(h.getLevel().registryAccess()).contains("MovedEntity"),"Empty virtual rope saves only controller extension metadata");h.succeed();}
    @GameTest public void loweringEmptyRopePicksUpTheActualWorldBodyOnItsNextNativeAssembly(GameTestHelper h)throws Exception{h.setBlock(B,AllBlocks.ROPE_PULLEY);h.setBlock(BODY,Blocks.BARREL);h.getBlockEntity(BODY,BarrelBlockEntity.class).setItem(0,cargo());var pulley=h.getBlockEntity(B,PulleyBlockEntity.class);drive(pulley,256);pulley.assemble();for(int i=0;i<30&&pulley.getMovedContraption()==null;i++)tick(h,pulley,1);var owner=pulley.getMovedContraption();h.assertTrue(owner!=null&&owner.getContraption() instanceof PulleyContraption c&&c.getInitialOffset()==2,"Real empty rope encounters the body and reassembles at its actual source depth");owned(h,owner);h.assertBlockPresent(Blocks.AIR,BODY);h.succeed();}
    @GameTest public void actualBodyStallHoldsBothExtensionAndPersistedSequenceReceipt(GameTestHelper h)throws Exception{var pulley=setup(h,false);var owner=start(h,pulley,256);var context=SequencedGearshiftBlockEntity.SequenceContext.fromGearshift(SequencerInstructions.TURN_DISTANCE,pulley.getTheoreticalSpeed(),1);pulley.applySequenceContext(context,new SequencePhase(h.absolutePos(B.west(6)),1));owner.setStalled(true);tick(h,pulley,5);h.assertTrue(pulley.offset==2&&pulley.saveWithFullMetadata(h.getLevel().registryAccess()).getDoubleOr("SequencedOffsetLimit",-1)==1,"Actual stall consumes no extension or sequenced travel");owner.setStalled(false);tick(h,pulley,5);h.assertTrue(Math.abs(pulley.offset-3)<1e-6&&pulley.getMovedContraption()==owner,"Final source step clamps to exact one block without retiring actual native body");owned(h,owner);h.succeed();}
    @GameTest public void emptyRopeAlsoRetainsConsumedSamePhaseDistanceAcrossNativeReload(GameTestHelper h)throws Exception{h.setBlock(B,AllBlocks.ROPE_PULLEY);var pulley=h.getBlockEntity(B,PulleyBlockEntity.class);drive(pulley,256);var context=SequencedGearshiftBlockEntity.SequenceContext.fromGearshift(SequencerInstructions.TURN_DISTANCE,pulley.getTheoreticalSpeed(),1);var phase=new SequencePhase(h.absolutePos(B.west(6)),1);pulley.applySequenceContext(context,phase);pulley.assemble();tick(h,pulley,5);h.assertTrue(Math.abs(pulley.offset-1)<1e-6&&pulley.getMovedContraption()==null,"Real empty extension clamps to source sequence without a fake body");var data=pulley.saveWithFullMetadata(h.getLevel().registryAccess());var copy=(PulleyBlockEntity)BlockEntity.loadStatic(h.absolutePos(B),h.getBlockState(B),data,h.getLevel().registryAccess());copy.setLevel(h.getLevel());h.getLevel().setBlockEntity(copy);drive(copy,256);copy.applySequenceContext(context,phase);tick(h,copy,5);h.assertTrue(Math.abs(copy.offset-1)<1e-6&&copy.getMovedContraption()==null,"Same saved phase cannot refill consumed empty-rope travel");h.succeed();}
    private static PulleyBlockEntity mirrorFixture(GameTestHelper h)throws Exception{var root=setup(h,false);var mirror=B.east(2);h.setBlock(mirror,AllBlocks.ROPE_PULLEY);h.setBlock(mirror.below(),AllBlocks.ROPE);h.setBlock(mirror.below(2),AllBlocks.PULLEY_MAGNET);h.setBlock(BODY.east(),Blocks.STONE);h.setBlock(BODY.east(2),Blocks.STONE);h.assertTrue(h.getLevel().addFreshEntity(new SuperGlueEntity(h.getLevel(),SuperGlueEntity.span(h.absolutePos(BODY),h.absolutePos(BODY.east(2))))),"Real broad body glue accepted");start(h,root,16);return root;}
    @GameTest public void mirroredNativePulleysShareOneActualBodyUuidAndNeverCopyItsCargo(GameTestHelper h)throws Exception{var root=mirrorFixture(h);var owner=root.getMovedContraption();var mirror=h.getBlockEntity(B.east(2),PulleyBlockEntity.class);h.assertTrue(mirror.getMovedContraption()==null&&mirror.getAttachedContraption()==owner&&mirror.getMirrorParent().equals(h.absolutePos(B))&&mirror.getMirrorOwner().equals(owner.getUUID()),"Passive native mirror resolves the one original actual cargo body");tick(h,root,3);PulleyBlockEntity.tick(h.getLevel(),h.absolutePos(B.east(2)),h.getBlockState(B.east(2)),mirror);h.assertTrue(mirror.offset==root.offset,"Native mirror extension follows the actual owning controller");h.assertFalse(mirror.saveWithFullMetadata(h.getLevel().registryAccess()).contains("MovedEntity"),"Mirror saves relation metadata only, never another body/cargo owner");owned(h,owner);h.succeed();}
    @GameTest public void successfulOwningDisassemblyRestoresBothMirrorsPhysicalRopesAndExactBodyCargo(GameTestHelper h)throws Exception{var root=mirrorFixture(h);var mirror=h.getBlockEntity(B.east(2),PulleyBlockEntity.class);h.assertTrue(root.disassemble(),"Actual root body restores");PulleyMirrorRestoration.tick(h.getLevel());h.assertTrue(!mirror.isRunning()&&mirror.getMirrorParent()==null&&mirror.getAttachedContraption()==null,"Passive mirror retires only its actual relation after owning body completion");h.assertBlockPresent(AllBlocks.ROPE,B.east(2).below());h.assertBlockPresent(AllBlocks.PULLEY_MAGNET,B.east(2).below(2));h.assertTrue(exact(h.getBlockEntity(BODY,BarrelBlockEntity.class).getItem(0)),"Exactly seven original named diamonds are world-owned once");h.succeed();}
    @GameTest public void unbreakablePhysicalRopeTargetSurvivesRealBodyRestoration(GameTestHelper h)throws Exception{var pulley=setup(h,false);start(h,pulley,16);h.setBlock(B.below(),Blocks.BEDROCK);h.assertTrue(pulley.disassemble(),"Source rope generation skips actual unbreakable target after exact body placement");h.assertBlockPresent(Blocks.BEDROCK,B.below());h.assertBlockPresent(AllBlocks.PULLEY_MAGNET,B.below(2));h.assertTrue(exact(h.getBlockEntity(BODY,BarrelBlockEntity.class).getItem(0)),"Unbreakable rope target cannot delete or copy mounted body cargo");h.succeed();}
    @GameTest public void ropeLengthBreakPropagatesThroughActualNativeRopeBlocksToItsController(GameTestHelper h){var pulley=setup(h,false);h.getLevel().destroyBlock(h.absolutePos(B.below(2)),false);h.assertBlockPresent(Blocks.AIR,B.below());h.assertTrue(pulley.offset==0&&pulley.getInitialRopeOffset()==0,"Native rope removal invalidates the original length metadata without touching the world body");h.assertTrue(exact(h.getBlockEntity(BODY,BarrelBlockEntity.class).getItem(0)),"Broken stationary rope leaves original world cargo untouched");h.succeed();}
    @GameTest public void unloadedMirrorFinalizationSavedDataContainsOnlyPositionsOldUuidAndLength(GameTestHelper h){var far=new BlockPos(2200000,70,2200000);PulleyMirrorRestoration.finishOrQueue(h.getLevel(),far,far.east(2),UUID.randomUUID(),4);var data=h.getLevel().getDataStorage().computeIfAbsent(PulleyMirrorRestoration.TYPE);var ops=h.getLevel().registryAccess().createSerializationContext(net.minecraft.nbt.NbtOps.INSTANCE);var encoded=PulleyMirrorRestoration.CODEC.encodeStart(ops,data).getOrThrow();var text=encoded.toString();h.assertTrue(text.contains("Offset")&&text.contains("Owner")&&!text.contains("Contraption")&&!text.contains("Items")&&!text.contains("storage"),"Real SavedData contains no duplicate body, inventory or BE payload");h.assertTrue(h.getLevel().getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null,"Mirror finalization does not fabricate unloaded native chunks");h.succeed();}
    @GameTest public void actualNativeEntityLoaderPreservesTranslatedPositionControllerAndOriginalCargoUuid(GameTestHelper h)throws Exception{
        var pulley=setup(h,false);var original=start(h,pulley,100);tick(h,pulley,3);var actual=original.position();var id=original.getUUID();var output=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess());h.assertTrue(original.saveAsPassenger(output),"Native owned body serializes its actual translated Pos and ControllerRelative");original.remove(net.minecraft.world.entity.Entity.RemovalReason.UNLOADED_TO_CHUNK);h.assertTrue(pulley.getMovedContraption()==null&&pulley.isRunning(),"Absent actual owner keeps the saved UUID unresolved");
        var restored=net.minecraft.world.entity.EntityType.loadEntityRecursive(output.buildResult(),h.getLevel(),new net.minecraft.world.entity.EntitySpawnRequest(net.minecraft.world.entity.EntitySpawnReason.LOAD,false),net.minecraft.world.entity.EntityProcessor.NOP);h.assertTrue(restored instanceof LinearContraptionEntity&&restored.getUUID().equals(id)&&h.getLevel().addFreshEntity(restored),"Native type registry recreates the original real linear UUID");var owner=(LinearContraptionEntity)restored;h.assertTrue(owner.position().distanceToSqr(actual)<1e-12&&owner.getControllerPos().equals(h.absolutePos(B))&&pulley.getMovedContraption()==owner,"Native Pos must survive dynamic contraption binding until ControllerRelative decodes");owned(h,owner);h.succeed();
    }
    @GameTest public void realStabilizedChildFollowsNativePulleyPoseAndUnresolvedChildHoldsItsSequenceReceipt(GameTestHelper h)throws Exception{
        var pulley=setup(h,false);h.setBlock(BODY,Blocks.STONE);h.setBlock(BODY.east(),AllBlocks.MECHANICAL_BEARING.defaultBlockState().setValue(com.simibubi.create.content.contraptions.bearing.BearingBlock.FACING,Direction.UP));h.setBlock(BODY.east().above(),Blocks.BARREL);h.getBlockEntity(BODY.east().above(),BarrelBlockEntity.class).setItem(0,cargo());h.getLevel().addFreshEntity(new SuperGlueEntity(h.getLevel(),SuperGlueEntity.span(h.absolutePos(BODY),h.absolutePos(BODY.east()))));boolean previous=ContraptionSettings.stabiliseStableContraptions;
        try{ContraptionSettings.stabiliseStableContraptions=true;drive(pulley,100);var context=SequencedGearshiftBlockEntity.SequenceContext.fromGearshift(SequencerInstructions.TURN_DISTANCE,pulley.getTheoreticalSpeed(),1);pulley.applySequenceContext(context,new SequencePhase(h.absolutePos(B.west(6)),1));h.assertTrue(pulley.assemble(),"Actual pulley body and source stabilized child assemble");var owner=pulley.getMovedContraption();var graph=owner.getContraption().getStabilizedSubContraptions();var id=graph.children().keySet().iterator().next();var child=(OrientedContraptionEntity)h.getLevel().getEntity(id);tick(h,pulley,3);var expected=owner.toGlobalVector(Vec3.atCenterOf(graph.location(id).connected()),1).add(0,-.5,0);h.assertTrue(child.position().distanceToSqr(expected)<1e-10,"Real controller progress synchronizes the actual child anchor without a scripted passenger positioning call");float offset=pulley.offset;double remaining=pulley.saveWithFullMetadata(h.getLevel().registryAccess()).getDoubleOr("SequencedOffsetLimit",-1);child.remove(net.minecraft.world.entity.Entity.RemovalReason.UNLOADED_TO_CHUNK);tick(h,pulley,3);h.assertTrue(pulley.offset==offset&&pulley.saveWithFullMetadata(h.getLevel().registryAccess()).getDoubleOr("SequencedOffsetLimit",-1)==remaining&&graph.contains(id),"Actual unresolved child freezes native travel without dropping its original UUID or consuming its sequence receipt");h.assertFalse(pulley.disassemble(),"Real missing native child refuses early body and rope restoration");}finally{ContraptionSettings.stabiliseStableContraptions=previous;}h.succeed();
    }
}
